<template>
  <div class="page">
    <div class="page-heading"><div><router-link class="back" to="/staff"><ArrowLeft :size="15" />返回审核队列</router-link><h1>采集活动配置</h1><p>每个餐饮区只能属于一个分组；每组最多配置 200 道目标菜，首期建议 50 道。</p></div><button class="button secondary" :disabled="syncing" @click="sync"><RefreshCw :class="{spin:syncing}" :size="17" />同步目录</button></div>
    <div v-if="error" class="notice error"><CircleAlert :size="18" />{{ error }}</div><div v-if="message" class="notice success"><CheckCircle2 :size="18" />{{ message }}</div>
    <div v-if="loading" class="empty"><span class="spinner"></span></div>
    <template v-else-if="state">
      <div class="catalog-bar"><Database :size="18" /><span>目录版本 <strong>{{ state.catalogVersion }}</strong></span><span>{{ state.venues.length }} 个餐饮区</span></div>
      <div class="admin-grid">
        <aside><button v-for="group in state.groups" :key="group.id" :class="{active:selectedId===group.id}" @click="select(group.id)"><span><strong>{{ group.name }}</strong><small>{{ group.venueIds.length }} 个餐饮区 · {{ group.targets.length }} 道目标菜</small></span><ChevronRight :size="17" /></button></aside>
        <section v-if="form" class="editor">
          <div class="editor-head"><div><span>分组设置</span><strong>{{ form.name }}</strong></div><button class="button" :disabled="saving" @click="saveGroup"><Save :size="17" />保存分组</button></div>
          <div class="form-grid"><div class="field"><label>分组名称</label><input v-model.trim="form.name" maxlength="60" /></div><div class="field"><label>显示顺序</label><input v-model.number="form.displayOrder" type="number" min="1" max="20" /></div><div class="field full"><label>说明</label><input v-model.trim="form.description" maxlength="240" /></div></div>
          <div class="section-title"><h2>餐饮区映射</h2><span>已被其他分组使用的餐饮区不可选择</span></div>
          <div class="venue-options"><label v-for="venue in rootVenues" :key="venue.id" :class="{disabled:ownedByOther(venue.id)}"><input v-model="form.venueIds" type="checkbox" :value="venue.id" :disabled="ownedByOther(venue.id)" /><span><strong>{{ venue.name }}</strong><small v-if="ownedByOther(venue.id)">已属于 {{ ownerName(venue.id) }}</small></span></label></div>

          <div class="section-title"><h2>目标菜品</h2><span>{{ form.targets.length }}/200</span></div>
          <div class="target-search"><input v-model.trim="targetTerm" placeholder="在当前分组目录中搜索菜品" @keyup.enter="searchTargets" /><button class="button secondary" @click="searchTargets"><Search :size="17" />搜索</button></div>
          <div v-if="targetMatches.length" class="search-results"><button v-for="dish in targetMatches" :key="dish.dishId" :disabled="form.targets.some((item)=>item.dishId===dish.dishId)" @click="addTarget(dish)"><Plus :size="15" /><span><strong>{{ dish.name }}</strong><small>{{ dish.venue.name }} · {{ dish.stall.name }}</small></span></button></div>
          <div class="target-table"><div class="table-head"><span>菜品与位置</span><span>已通过/贡献者</span><span>目标</span><span></span></div><div v-for="target in form.targets" :key="target.dishId" class="target-row"><span><strong>{{ target.name }}</strong><small>{{ target.venue }} · {{ target.stall }}</small></span><span>{{ target.approved || 0 }} / {{ target.contributors || 0 }} 人</span><input v-model.number="target.goalImages" type="number" min="20" max="200" aria-label="目标图片数" /><button class="remove" title="移除目标菜" aria-label="移除目标菜" @click="removeTarget(target.dishId)"><Trash2 :size="16" /></button></div></div>
          <button class="button save-targets" :disabled="savingTargets" @click="saveTargets"><Save :size="17" />保存 {{ form.targets.length }} 道目标菜</button>
        </section>
      </div>
    </template>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import { ArrowLeft, CheckCircle2, ChevronRight, CircleAlert, Database, Plus, RefreshCw, Save, Search, Trash2 } from '@lucide/vue';
import { collectorApi } from '../api.js';
const state=ref(null),selectedId=ref(''),form=ref(null),loading=ref(true),saving=ref(false),savingTargets=ref(false),syncing=ref(false),error=ref(''),message=ref(''),targetTerm=ref(''),targetMatches=ref([]);
const selectedGroup=computed(()=>state.value?.groups.find(item=>item.id===selectedId.value));
const rootVenues=computed(()=>state.value?.venues.filter(item=>!item.parentId||item.kind!=='campus').filter(item=>item.kind!=='campus')||[]);
function flash(text){message.value=text;setTimeout(()=>{if(message.value===text)message.value='';},3500)}
async function load(){loading.value=true;error.value='';try{state.value=await collectorApi.adminState();select(selectedId.value||state.value.groups[0]?.id);}catch(reason){error.value=reason.message;}finally{loading.value=false;}}
function select(id){selectedId.value=id;const group=state.value?.groups.find(item=>item.id===id);form.value=group?JSON.parse(JSON.stringify(group)):null;targetMatches.value=[];targetTerm.value='';}
function ownedByOther(venueId){return state.value.groups.some(group=>group.id!==selectedId.value&&group.venueIds.includes(venueId));}
function ownerName(venueId){return state.value.groups.find(group=>group.id!==selectedId.value&&group.venueIds.includes(venueId))?.name||'';}
async function saveGroup(){saving.value=true;error.value='';try{state.value=await collectorApi.updateGroup(form.value.id,{name:form.value.name,description:form.value.description,displayOrder:form.value.displayOrder,active:form.value.active,venueIds:form.value.venueIds});select(selectedId.value);flash('分组配置已保存');}catch(reason){error.value=reason.message;}finally{saving.value=false;}}
async function searchTargets(){if(!targetTerm.value)return;try{targetMatches.value=(await collectorApi.search(form.value.id,targetTerm.value)).matches;}catch(reason){error.value=reason.message;}}
function addTarget(dish){if(form.value.targets.length>=200||form.value.targets.some(item=>item.dishId===dish.dishId))return;form.value.targets.push({dishId:dish.dishId,name:dish.name,venue:dish.venue.name,stall:dish.stall.name,goalImages:60,priority:0,approved:0,contributors:0});}
function removeTarget(id){form.value.targets=form.value.targets.filter(item=>item.dishId!==id);}
async function saveTargets(){savingTargets.value=true;error.value='';try{await collectorApi.updateTargets(form.value.id,form.value.targets.map((item,index)=>({dishId:item.dishId,goalImages:item.goalImages,priority:form.value.targets.length-index})));await load();flash('目标菜品已保存');}catch(reason){error.value=reason.message;}finally{savingTargets.value=false;}}
async function sync(){syncing.value=true;error.value='';try{const result=await collectorApi.syncCatalog();await load();flash(`已同步 ${result.dishes} 道菜`);}catch(reason){error.value=reason.message;}finally{syncing.value=false;}}
onMounted(load);
</script>

<style scoped>
.back{display:inline-flex;align-items:center;gap:4px;margin-bottom:8px;color:var(--brand);font-size:12px}.catalog-bar{display:flex;align-items:center;gap:12px;margin-bottom:14px;padding:11px 14px;border:1px solid var(--line);border-radius:5px;color:#596169;background:white;font-size:12px}.catalog-bar span:last-child{margin-left:auto}.catalog-bar strong{color:#30363b}.admin-grid{display:grid;grid-template-columns:240px minmax(0,1fr);gap:14px;align-items:start}aside{display:grid;overflow:hidden;border:1px solid var(--line);border-radius:6px;background:white}aside button{display:grid;grid-template-columns:1fr 17px;align-items:center;gap:8px;padding:14px;border:0;border-bottom:1px solid var(--line);background:white;text-align:left;cursor:pointer}aside button:last-child{border-bottom:0}aside button.active{color:var(--brand);background:var(--brand-soft)}aside strong,aside small{display:block}aside strong{font-size:13px}aside small{margin-top:4px;color:var(--muted);font-size:10px}.editor{padding:20px;border:1px solid var(--line);border-radius:6px;background:white;box-shadow:var(--shadow)}.editor-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:17px;border-bottom:1px solid var(--line)}.editor-head span,.editor-head strong{display:block}.editor-head span{color:var(--muted);font-size:10px}.editor-head strong{margin-top:3px}.form-grid{display:grid;grid-template-columns:1fr 160px;gap:12px;margin-top:18px}.form-grid .full{grid-column:1/-1}.venue-options{display:grid;grid-template-columns:1fr 1fr;gap:7px}.venue-options label{display:grid;grid-template-columns:18px 1fr;gap:7px;min-height:52px;align-items:center;padding:9px;border:1px solid var(--line);border-radius:5px}.venue-options label.disabled{opacity:.55;background:#f3f4f5}.venue-options input{accent-color:var(--brand)}.venue-options strong,.venue-options small{display:block}.venue-options strong{font-size:12px}.venue-options small{margin-top:3px;color:var(--muted);font-size:10px}.target-search{display:grid;grid-template-columns:1fr auto;gap:7px}.target-search input{min-width:0;height:42px;padding:0 11px;border:1px solid #cfd3d7;border-radius:5px}.search-results{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px;padding:8px;border:1px solid var(--line);border-radius:5px;background:#f7f8f9}.search-results button{display:grid;grid-template-columns:16px 1fr;gap:7px;padding:8px;border:0;border-radius:4px;background:white;text-align:left;cursor:pointer}.search-results button:disabled{opacity:.45}.search-results strong,.search-results small{display:block}.search-results strong{font-size:11px}.search-results small{margin-top:2px;color:var(--muted);font-size:9px}.target-table{margin-top:12px;border:1px solid var(--line);border-radius:5px}.table-head,.target-row{display:grid;grid-template-columns:minmax(180px,1fr) 110px 70px 34px;align-items:center;gap:8px;padding:8px 10px}.table-head{color:var(--muted);background:#f2f4f5;font-size:10px}.target-row{border-top:1px solid var(--line);font-size:11px}.target-row strong,.target-row small{display:block}.target-row small{margin-top:2px;color:var(--muted);font-size:9px}.target-row input{width:64px;height:32px;padding:0 5px;border:1px solid #cfd3d7;border-radius:4px}.remove{display:grid;width:30px;height:30px;place-items:center;border:0;border-radius:4px;color:var(--brand);background:transparent;cursor:pointer}.remove:hover{background:var(--brand-soft)}.save-targets{margin-top:12px;margin-left:auto}.spin{animation:spin .8s linear infinite}
@media(max-width:760px){.admin-grid{grid-template-columns:1fr}aside{grid-template-columns:repeat(4,minmax(0,1fr));overflow-x:auto}aside button{grid-template-columns:1fr;border-bottom:0;border-right:1px solid var(--line);padding:10px}aside svg{display:none}aside strong{font-size:11px}aside small{font-size:8px}.editor{padding:14px}.venue-options,.search-results{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}.table-head,.target-row{grid-template-columns:minmax(130px,1fr) 80px 58px 28px;padding:7px 6px}.target-row>span:nth-child(2){font-size:9px}}
</style>
